function addFilter(){if(!filterColumn.value)return;let value=filterValue.value;if(filterColumn.value==='system.updated_at'&&filterOperator.value!=='unset'){const time=new Date(value);if(!value||!Number.isFinite(time.getTime())){localError.value='请选择有效的最后修改时间。';return;}value=time.toISOString();}filters.value.push({column:filterColumn.value,operator:filterOperator.value,...(filterOperator.value!=='unset'?{value}:{})});page.value=1;void load();showFilter.value=false;}
function executeQuery(){if(engine.value==='model'&&!allowExternal.value)return;activeQuery.value=prompt.value.trim()?{prompt:prompt.value.trim(),engine:engine.value,allowExternalSchema:allowExternal.value}:undefined;page.value=1;void load();}
function clearFilters(){search.value='';filters.value=[];prompt.value='';activeQuery.value=undefined;page.value=1;void load();}
function selectPage(checked:boolean){const pageIds=new Set(viewRows.value.map(row=>row.id));selectedRows.value=(checked?[...new Set([...selectedRows.value,...assignablePageIds.value])]:selectedRows.value.filter(id=>!pageIds.has(id))).filter(id=>!rowDeleted(id)).slice(0,500);}
function toggleRow(id:string,checked:boolean){if(historical.value||serverDraftIssue.value||rowDeleted(id)||!(snapshot.value?.capabilities?.editContent===true&&rowMay(id,'editContent')||snapshot.value?.capabilities?.assignLabels===true&&rowMay(id,'assignLabels'))){selectedRows.value=selectedRows.value.filter(item=>item!==id);return;}selectedRows.value=checked?[...new Set([...selectedRows.value,id])].filter(item=>!rowDeleted(item)).slice(0,500):selectedRows.value.filter(item=>item!==id);}
function bulkApply(){const valid=bulkCandidateIds.value;if(!valid.length||valid.length>500)return;selectedRows.value=valid;for(const id of valid)queueLabels('row',bulkValues.value,id);drawer.value='';app.notify(`${valid.length} 条样本的批量标签已加入草稿列表。`);}

async function submitFeedback(){if(!feedback.value.trim()||saving.value)return;if(feedback.value.trim().length>2000){localError.value='缺项反馈最多 2000 字。';return;}saving.value=true;try{await post(props.base+'/schema/feedback',{reason:feedback.value.trim()});feedback.value='';drawer.value='';app.notify('反馈已发送到组织规范维护队列。');}catch(cause){localError.value=(cause as Error).message;}finally{saving.value=false;}}
function normalized(value:unknown):unknown{return Array.isArray(value)?value.map(normalized):value!==null&&typeof value==='object'?Object.fromEntries(Object.entries(value).sort(([a],[b])=>a<b?-1:a>b?1:0).map(([key,item])=>[key,normalized(item)])):value;}
async function hash(value:unknown){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(normalized(value))));return Array.from(new Uint8Array(digest)).map(byte=>byte.toString(16).padStart(2,'0')).join('');}
watch([finePointer,fineKind,fineTargets],()=>{fineText.value=String(fineTargets.value.find(item=>item.pointer===finePointer.value)?.value??'');});
function captureSelection(event:Event){const field=event.target as HTMLTextAreaElement;fineStart.value=Array.from(field.value.slice(0,field.selectionStart)).length;fineEnd.value=Array.from(field.value.slice(0,field.selectionEnd)).length;}
async function addFine(){try{const target=fineTargets.value.find(item=>item.pointer===finePointer.value);if(!target)throw new Error('请选择实际字段或步骤。');const values=Object.fromEntries(Object.entries(fineValues.value).filter((entry):entry is [string,string|string[]]=>entry[1]!==null));if(!Object.keys(values).length)throw new Error('请为该片段或步骤选择标签。');const annotation={id:crypto.randomUUID(),pointer:target.pointer,sourceHash:await hash(target.value),values,...(fineNote.value?{note:fineNote.value}:{})};const spans=[...fineAnnotations.value.spans],steps=[...fineAnnotations.value.steps];if(fineKind.value==='span'){if(typeof target.value!=='string'||fineStart.value>=fineEnd.value||fineEnd.value>Array.from(target.value).length)throw new Error('请选择有效的 Unicode 码点范围。');spans.push({...annotation,start:fineStart.value,end:fineEnd.value});}else steps.push(annotation);queueFine(spans,steps);drawer.value='';fineValues.value={};fineNote.value='';}catch(cause){localError.value=(cause as Error).message;}}
function queueFine(spans:DatasetSpan[],steps:DatasetStep[]){if(!selected.value||!canAssign.value||cancelledAppendIds.value.has(selected.value))return;pending.value=stageDatasetFineAnnotations(pending.value,selected.value,labelValues('row',selected.value),spans,steps,changeBase());}
function removeFine(id:string){queueFine(fineAnnotations.value.spans.filter(item=>item.id!==id),fineAnnotations.value.steps.filter(item=>item.id!==id));}
function openFine(){if(!stageEditing())return;finePointer.value='';fineValues.value={};fineNote.value='';localError.value='';drawer.value='fine';}
function openAttachment(filename:string){attachment.value=filename;drawer.value='file';}
async function closeDrawer(){if(saving.value)return;if(drawerDirty.value&&!await app.confirmAction('当前面板内容尚未加入草稿列表，确认放弃并关闭？',{title:'未保存的面板内容',confirmLabel:'放弃并关闭'}))return;const restoreLabelFocus=drawer.value==='labels';if(drawer.value==='source-bulk'){sourceBulkIds.value=[];sourceBulkRows.value=[];sourceBulkRequest.value=undefined;sourceBulkError.value='';}drawer.value='';if(restoreLabelFocus)void nextTick(()=>tableViewport.value?.querySelector<HTMLElement>('tr[data-row-id="'+CSS.escape(selected.value)+'"] .dw-label-actions button')?.focus({preventScroll:true}));}
function sourceFieldSorted(name:string){return sort.value?.column===name||sort.value?.column==='data.'+name;}
async function sortBy(column:string){if(!stageEditing())return;sort.value=sort.value?.column!==column?{column,direction:'asc'}:sort.value.direction==='asc'?{column,direction:'desc'}:undefined;page.value=1;await load();}
async function initializeEmpty(addFirst=false){
  if(!emptySetup.value?.canInitialize||historical.value||saving.value)return;
  const context={base:props.base,branch:props.branch,principal:principal.value,head:emptySetup.value.commitId};
  if(!await app.confirmAction('将建立空数据集入口并产生一次配置提交；不会生成示例样本。之后添加或编辑的样本仍进入私有草稿，最后由你提交。',{title:'建立空数据集',confirmLabel:addFirst?'建立并添加首条样本':'建立空数据集'}))return;
  if(context.base!==props.base||context.branch!==props.branch||context.principal!==principal.value)return;
  saving.value=true;error.value='';try{const result=await post<{commitId:string;totalRows:number}>(context.base+'/dataset/initialize-empty',{ref:context.branch,expectedCommit:context.head});if(context.base!==props.base||context.branch!==props.branch||context.principal!==principal.value)return;emptySetup.value=undefined;emit('saved',result);checkpointChecked=false;await load(true);saving.value=false;if(addFirst)append();}catch(cause){error.value=(cause as Error).message;}finally{saving.value=false;}
}
function openImport(){if(historical.value||saving.value)return;if(dirty.value||hasUncommitted.value){app.notify('当前分支有待处理的编辑草稿。请先完成提交或选择新的工作分支导入；当前输入会继续保留。');return;}importOpen.value=true;}
async function imported(result:{commitId:string;totalRows:number}){importOpen.value=false;sessionCommitted.value={};clearBaseCache();emptySetup.value=undefined;checkpointChecked=false;emit('saved',result);await load(true);}
async function refresh():Promise<boolean>{if(!await mayLeave())return false;sessionCommitted.value={};clearBaseCache();pending.value=[];cellEdit.value=undefined;editing.value=false;drawer.value='';inspectorOpen.value=false;checkpointChecked=false;checkpointReady.value=false;await load(true);return !error.value;}
defineExpose({refresh,hasUnsaved:dirty,hasDraft:hasUncommitted});
const rawUrl=computed(()=>'/api'+props.base+'/raw'+queryString({ref:pinned.value,path:attachment.value}));
</script>

<template><section class="dataset-workbench" aria-label="数据编辑工作台">
  <header class="dw-header"><div><Database :size="19"/><h2>数据编辑</h2><span v-if="snapshot" class="dw-count">{{snapshot.totalRows.toLocaleString()}} 条样本</span><span v-if="snapshot" class="dw-version"><GitBranch :size="13"/>{{viewContext}}</span></div><div class="dw-actions"><button class="btn" :disabled="loading||saving" @click="refresh"><RefreshCw :size="14"/>刷新版本</button><button class="btn" :disabled="!snapshot" @click="emit('edit-project-labels')"><Tags :size="14"/>项目标签</button><button class="btn" :disabled="(!canAddRows&&!emptySetup?.canInitialize)||saving||historical||dirty||hasUncommitted" title="导入前须处理当前分支的私有草稿" @click="openImport"><Upload :size="14"/>导入样本</button><button class="btn" :disabled="!canAddRows||saving" @click="append"><Plus :size="14"/>添加样本</button></div></header>
  <div v-if="snapshot" class="dw-layout-toolbar"><div><Columns3 :size="15"/><span>拖动列头手柄排列，拖动右侧分隔条调宽</span><small>{{layoutDirty?'布局有未保存调整':'我的表格布局'}} · 不修改样本或分支</small></div><button v-if="layoutDirty" class="btn" :disabled="layoutLoading||layoutSaving" @click="undoLayoutAdjustments">撤销布局调整</button><button class="btn" :disabled="layoutLoading||layoutSaving||!visualLayout.order.length&&!Object.keys(visualLayout.widths).length" @click="defaultTableLayout">恢复默认布局</button><button v-if="layoutConflict" class="btn" :disabled="layoutLoading||layoutSaving" @click="recheckTableLayout">保留拖动并核对最新布局</button><button class="btn" :disabled="!layoutDirty||layoutLoading||layoutSaving||!layoutReady||layoutConflict||!canUsePrivateDrafts" :title="canUsePrivateDrafts?'仅保存当前身份在此项目分支的列顺序与宽度':'登录后可保存个人布局'" @click="saveTableLayout"><LoaderCircle v-if="layoutSaving" class="spin" :size="14"/><Save v-else :size="14"/>{{layoutSaving?'正在保存布局…':'保存我的表格布局'}}</button></div>
  <p v-if="layoutError" class="dw-layout-message dw-error" role="alert">{{layoutError}}<button v-if="!layoutReady" class="dw-text-button" @click="loadTableLayout">重新读取布局</button></p><p v-else-if="layoutNotice" class="dw-layout-message" role="status">{{layoutNotice}}</p>
  <div v-if="serverDraftSummary" class="dw-server-draft"><div><strong>{{serverDraftIssue?'本机草稿暂不可应用':'正在预览我的私有草稿'}}</strong><span>基点 {{serverDraftSummary.baseCommit.slice(0,10)}} · 草稿 r{{serverDraftSummary.draftRevision}} · {{serverDraftSummary.operationCount}} 项更改</span><p>{{serverDraftIssue?.message??'仅自己可见，分支尚未产生提交；筛选和分页包含草稿。'}}</p></div><button v-if="!serverDraftIssue" class="btn" :disabled="saving" @click="inspectDiff">查看变更</button><button class="btn" :disabled="saving" @click="downloadServerDraft"><Download :size="13"/>下载本机草稿</button><button class="btn" :disabled="saving" @click="discardServerDraft">放弃草稿</button></div>
  <div v-if="needsDraftSync" class="dw-draft-sync"><div><strong>分支已有新版本，当前样本修改仍保留</strong><p>草稿基点 {{recoveryBase?.slice(0,10)}} → 当前分支 {{latestCommit?.slice(0,10)}}。仅项目标签或纯展示配置变化可显式同步；正文或样本规范改变将拒绝，不能覆盖他人修改。</p></div><button class="btn" :disabled="loading||saving||drawerDirty" @click="syncProjectLabelVersion"><RefreshCw :size="13"/>同步元数据版本</button></div>
  <p v-if="historical" class="dw-notice">当前正在查看固定历史版本；内容与标签只读。</p>
  <div v-if="checkpointSavedAt||checkpointSaving||checkpointError||draftIssue" class="dw-draft-banner"><div><strong>{{checkpointError?'输入保留失败':draftIssue?'先前输入需要对照':checkpointSaving?'正在保留原始输入…':checkpointRecovered?'已恢复上次工作台输入':'原始输入已自动保留'}}</strong><p>{{checkpointError||draftIssue||`保存于 ${checkpointSavedAt}；仅保留此身份的私有输入，不产生提交。`}}</p><details v-if="retainedInputs.length" @toggle="showCheckpointInput=($event.target as HTMLDetailsElement).open"><summary>查看先前输入（只读，未套用）· {{retainedInputs.length}} 份</summary><pre v-if="showCheckpointInput">{{datasetSourcePreview(reviewCheckpoint,12000)}}</pre><p>基点或规则改变的输入不会自动覆盖当前分支。下载完整副本可人工对照。</p></details></div><button v-if="checkpointConflict" class="btn" :disabled="checkpointSaving||checkpointRecovering" @click="recoverCheckpoint">保留两份输入并重试</button><button v-else-if="checkpointError" class="btn" :disabled="checkpointSaving||checkpointRecovering" @click="preserveDraft">重试保留输入</button><button v-if="reviewCheckpoint" class="btn" @click="downloadDraft">下载保存输入</button><button v-if="reviewCheckpoint" class="btn btn-ghost" @click="app.confirmAction('删除此身份在当前分支保存的工作台输入及只读对照副本？当前内存编辑与有效本机草稿不会删除。').then(ok=>{if(ok)void removeStoredDraft();})">删除输入副本</button></div>
  <p v-if="error" class="dw-error" role="alert">{{error}} <span v-if="dirty">本地草稿仍保留。</span></p>
  <div v-if="!snapshot&&loading" class="dw-empty" role="status"><LoaderCircle class="spin" :size="26"/><strong>正在读取当前分支的数据集…</strong></div>
  <div v-else-if="!snapshot&&!loading" class="dw-empty"><Database :size="32"/><h3>{{emptySetup?.canInitialize?'开始建立这个分支的数据集':emptySetup?.candidates.length?'需要配置规范数据入口':'当前分支尚无可用数据集'}}</h3><p>{{emptySetup?.canInitialize?'导入CSV、JSONL或ZIP样本，或建立空数据集后添加首条样本。README始终作为项目说明单独展示。':emptySetup?.candidates.length?'发现多个已有数据文件，请由负责人在项目设置选择规范入口；不会猜测或覆盖已有文件。':'有权限的负责人可以建立或配置数据集。'}}</p><div class="dw-empty-actions" v-if="emptySetup?.canInitialize&&!historical"><button class="btn btn-primary" :disabled="saving" @click="openImport"><Upload :size="14"/>导入样本</button><button class="btn" :disabled="saving" @click="initializeEmpty(true)"><Plus :size="14"/>手动添加首条样本</button><button class="btn btn-ghost" :disabled="saving" @click="initializeEmpty(false)">建立空数据集</button></div><button v-else-if="emptySetup?.candidates.length" class="btn" @click="router.push({path:base+'/settings',query:{branch}})">前往项目设置</button><button v-else class="btn" @click="refresh">刷新</button></div>
  <template v-if="snapshot"><form class="dw-searchbar" @submit.prevent="page=1;load()"><label><Search :size="16"/><input v-model="search" placeholder="搜索全部样本内容与标签…" aria-label="搜索全部样本"/></label><button class="btn" :disabled="loading">搜索</button><button type="button" class="btn" @click="showFilter=!showFilter"><Filter :size="14"/>条件筛选<span v-if="filters.length">{{filters.length}}</span></button><button type="button" class="btn dw-columns-button" @click="showColumns=!showColumns"><Columns3 :size="14"/>列</button></form>
  <form class="dw-querybar" @submit.prevent="executeQuery"><MessageSquareText :size="15"/><input v-model="prompt" placeholder="本地规则查询，例如 label 等于 malicious；按 score 降序" aria-label="样本查询问题"/><select v-model="engine" aria-label="查询引擎"><option value="rules">本地规则</option><option value="model">模型计划</option></select><button class="btn" :disabled="loading||engine==='model'&&!allowExternal">执行查询</button><label v-if="engine==='model'" class="dw-consent"><input v-model="allowExternal" type="checkbox"/>仅将字段结构与问题发送至 OpenAI</label></form>
  <p v-if="activeQuery&&(activeQuery.prompt!==prompt.trim()||activeQuery.engine!==engine)" class="dw-query-draft">查询输入尚未执行，当前继续显示上次已执行的查询结果。</p><form v-if="showFilter" class="dw-filter-builder" @submit.prevent="addFilter"><select v-model="filterColumn" aria-label="筛选字段"><option value="">选择字段或标签</option><optgroup label="样本字段"><option v-for="column in snapshot.columns.filter(item=>item.name!=='__bundle_provenance')" :key="column.name" :value="'data.'+column.name">{{column.name}}</option></optgroup><optgroup v-for="scope in ['label','dataset','file','span','step']" :key="scope" :label="scope==='label'?'样本标签':scope==='dataset'?'数据集标签':scope==='file'?'文件标签':scope==='span'?'字符片段标签':'步骤标签'"><option v-for="column in scopeColumns(scope==='dataset'?'dataset':scope==='file'?'file':'row')" :key="column.id" :value="scope+'.'+column.id">{{column.name}}</option></optgroup><optgroup label="系统操作记录（不导出）"><option value="system.updated_at">最后修改时间</option><option value="system.actor">最后操作人</option></optgroup><optgroup label="系统工作流"><option value="workflow.status">系统状态</option></optgroup></select><select v-model="filterOperator" aria-label="筛选操作"><option value="eq">等于</option><option value="contains">包含</option><option value="unset">未填写</option><option value="gt">大于</option><option value="lt">小于</option></select><input v-if="filterOperator!=='unset'" v-model="filterValue" :type="filterColumn==='system.updated_at'?'datetime-local':'text'" :step="filterColumn==='system.updated_at'?1:undefined" :placeholder="filterColumn==='system.updated_at'?'本地时间':'比较值'" :aria-label="filterColumn==='system.updated_at'?'最后修改时间筛选值':'筛选值'"/><button class="btn btn-primary">添加条件</button></form>
  <div v-if="showColumns" class="dw-column-picker"><div class="dw-column-summary">已显示 {{displayedColumns.length}} / {{availableTableColumns.length}} 个可展示样本字段<button type="button" class="btn btn-ghost" @click="visibleColumns=allColumns.map(column=>column.name)">显示全部字段</button><small v-if="allColumns.length>availableTableColumns.length">项目设置已隐藏 {{allColumns.length-availableTableColumns.length}} 个字段，需由有权限的人员在“样本字段”中重新勾选展示。</small><small>系统操作记录固定展示，不加入样本导出。</small></div><label v-for="column in availableTableColumns" :key="column.name"><input v-model="visibleColumns" type="checkbox" :value="column.name"/>{{column.name==='__bundle_provenance'?'来源证据':column.name}}<small v-if="columnHeaders[column.name]?.displayName">{{columnHeaders[column.name]?.displayName}}</small></label></div>
  <div v-if="filters.length||search||prompt" class="dw-filters"><span v-for="(item,index) in filters" :key="index">{{item.column}} {{item.operator}} {{item.value}}<button :aria-label="'移除条件'+(index+1)" @click="filters.splice(index,1);page=1;load()"><X :size="12"/></button></span><button @click="clearFilters">清除全部条件</button></div>
  <div v-if="snapshot.querySummary" class="dw-query-summary"><strong>{{snapshot.queryResult?'查询结果':`查询匹配 ${snapshot.querySummary.matchedRows.toLocaleString()} 条`}}</strong><span v-if="snapshot.querySummary.truncated"> · 返回前 {{snapshot.querySummary.returnedRows}} 条，未显示的结果不会伪造分页。</span><details><summary>查看查询说明</summary><p>{{snapshot.querySummary.explanation}}</p></details><div v-if="snapshot.queryResult" class="dw-query-results"><table><thead><tr><th v-for="column in snapshot.queryResult.columns" :key="column.name">{{column.name}}</th></tr></thead><tbody><tr v-for="(row,index) in snapshot.queryResult.rows" :key="index"><td v-for="column in snapshot.queryResult.columns" :key="column.name">{{display(row[column.name])}}</td></tr></tbody></table><p>下方保留当前筛选的样本，统计结果不直接作为可编辑样本。</p></div></div><div class="dw-resultbar"><span>匹配 <strong>{{snapshot.matchedRows.toLocaleString()}}</strong> / {{snapshot.totalRows.toLocaleString()}} 条 · 每页 {{snapshot.pageSize}} 条</span><span v-if="selectedRows.length" class="dw-selection">已选择 {{selectedRows.length}} 条（当前页 {{selectedOnPage}} 条）<button :disabled="historical||!!serverDraftIssue||saving" @click="openSourceBulk">批量编辑</button><button :disabled="!bulkCandidateIds.length" @click="bulkValues={};drawer='bulk'">批量标注</button><button @click="selectedRows=[]">取消选择</button></span><span v-if="snapshot.labelConflicts.length" class="dw-warning">{{snapshot.labelConflicts.length}} 项独立标注不一致，需复核裁决</span><LoaderCircle v-if="loading" class="spin" :size="15"/></div>
  <p v-if="selectedRows.length" class="dw-selection-scope">筛选与翻页不会扩大操作范围；保留已选身份，其中 {{selectedRows.length-selectedOnPage}} 条位于其他页或当前筛选之外。批量操作前可核对实际可处理条目。</p>
  <div class="dw-change-legend" aria-label="修改状态"><span class="dw-pending-key">● 未提交 {{statusCounts.pending}} 行</span><span class="dw-committed-key">✓ 本轮已提交 {{statusCounts.committed}} 行<span v-if="statusCounts.deleted">（含删除 {{statusCounts.deleted}} 行）</span></span><small>保存私有草稿仍为红色；提交成功变绿，绿色不代表复核通过。刷新版本或重新进入后清除绿色。悬停单元格可对照前后值。</small></div>
  <p class="dw-grid-help">点击序号查看详情；正文可选择复制 · 双击可编辑内容或人工标签 · Enter 加入草稿 · Shift + Enter 换行 · Esc 取消；身份、来源及源真值字段只读。</p>
  <div class="dw-layout"><div class="dw-grid" :class="{'dw-grid-resizing':resizingColumn}"><div ref="tableViewport" class="dw-table-scroll"><table :style="{width:tableWidth+'px'}">
    <colgroup><col style="width:var(--workbench-check-width,32px)"/><col style="width:var(--workbench-number-width,64px)"/><col v-for="item in presentationColumns" :key="item.key" :style="{width:tableLayout.widths[item.key]+'px'}"/></colgroup>
    <thead><tr><th class="dw-check"><input type="checkbox" aria-label="选择本页可处理样本" :disabled="!assignablePageIds.length" :checked="assignablePageIds.length>0&&assignablePageIds.every(id=>selectedRows.includes(id))" @change="selectPage(($event.target as HTMLInputElement).checked)"/></th><th class="dw-number">#</th><th v-for="item in presentationColumns" :key="item.key" :data-column-key="item.key" class="dw-visual-th" :class="item.kind==='source'?'dw-column-'+columnLayouts[item.column.name]?.kind:'dw-system-header'" :aria-sort="item.kind==='labels'?undefined:visualHeader(item).direction==='asc'?'ascending':visualHeader(item).direction==='desc'?'descending':'none'"><DatasetColumnHeader :column-key="item.key" :drop-side="columnDropTarget?.key===item.key?(columnDropTarget.after?'after':'before'):undefined" :name="visualHeader(item).name" :alias="visualHeader(item).alias" :description="visualHeader(item).description" :sort-name="visualHeader(item).sortName" :sortable="item.kind!=='labels'" :direction="visualHeader(item).direction" :width="tableLayout.widths[item.key]??158" :disabled="layoutLoading||layoutSaving||!layoutReady" @drag-target="(key,after)=>columnDropTarget=key?{key,after}:undefined" @sort="sortBy(visualHeader(item).column)" @move="moveColumn" @move-step="moveColumnStep(item.key,$event)" @resize="resizeColumn(item.key,$event)" @reset-width="resetColumnWidth(item.key)" @resizing="columnResizeActive"/></th></tr></thead>
    <tbody><tr v-for="(row,index) in viewRows" :key="row.id" :data-row-id="row.id" :aria-selected="selected===row.id" :data-edit-state="rowEditState(row.id)" :class="{selected:selected===row.id,'dw-row-modified':rowEditState(row.id)==='modified','dw-row-committed':rowEditState(row.id)==='committed','dw-row-deleted':rowDeleted(row.id)}">
      <td class="dw-check" @click.stop><input type="checkbox" :aria-label="'选择样本'+(row.data.id??row.data.uid??index+1)" :disabled="historical||!!serverDraftIssue||!(rowCanEdit(row.id)||snapshot.capabilities?.assignLabels&&rowMay(row.id,'assignLabels'))||rowDeleted(row.id)" :checked="selectedRows.includes(row.id)" @change="toggleRow(row.id,($event.target as HTMLInputElement).checked)"/></td>
      <td class="dw-number" @click="openSample(row.id,$event)"><button type="button" class="dw-row-details-trigger" :aria-label="'查看样本'+display(row.data.id??row.data.uid??row.id)+'详情'" :aria-expanded="inspectorOpen&&selected===row.id" @click.stop="openSample(row.id,$event)"><span v-if="row.isNew" class="dw-new-row" title="本机尚未保存的新样本">新</span><span v-else>{{(page-1)*snapshot.pageSize+index+1}}</span><small v-if="rowEditState(row.id)" class="dw-row-state" :title="rowStateText(row.id)">{{rowStateBadge(row.id)}}</small></button></td>
      <template v-for="item in presentationColumns" :key="item.key"><td v-if="item.kind==='labels'" class="dw-label-cell" :data-edit-state="labelsEditState(row.id)" :class="{'dw-cell-modified':labelsEditState(row.id)==='modified','dw-cell-committed':labelsEditState(row.id)==='committed','dw-label-editable':rowCanAssign(row.id)}" :title="rowLabelsHelp(row.id)" @dblclick.stop="editRowLabels(row.id)"><span v-if="rowDeleted(row.id)" class="dw-muted">待删除</span><template v-else><small v-if="labelsEditState(row.id)" class="dw-label-change-text">{{labelsEditState(row.id)==='modified'?'标签未提交':'标签已提交'}}</small><span v-for="(value,key) in labelCellValues(row.id)" :key="key" class="dw-label-chip">{{scopeColumns('row').find(column=>column.id===key)?.name??key}}: {{displayLabel(String(key),value)}}</span><span v-if="!Object.keys(labelCellValues(row.id)).length" class="dw-muted">尚未标注</span><div class="dw-label-actions"><button type="button" :aria-label="'编辑样本'+display(row.data.id??row.data.uid??row.id)+'人工标签'" :disabled="!rowCanAssign(row.id)" :title="rowLabelsHelp(row.id)" @click.stop="editRowLabels(row.id)"><Tags :size="13"/>编辑</button></div></template></td><td v-else-if="item.kind==='source'" :data-edit-state="cellEditState(row.id,item.column.name)" :title="cellStateTitle(row.id,item.column.name)" :class="['dw-column-'+columnLayouts[item.column.name]?.kind,{'dw-cell-modified':cellEditState(row.id,item.column.name)==='modified','dw-cell-committed':cellEditState(row.id,item.column.name)==='committed','dw-cell-editable':rowCanEdit(row.id)&&!sourceFieldIsReadOnly(item.column.name,snapshot.descriptor.identityField,row.data),'dw-cell-editing':cellEdit?.rowId===row.id&&cellEdit?.field===item.column.name}]" @dblclick.stop="beginCell(row.id,item.column.name)">
        <div v-if="cellEdit&&cellEdit.rowId===row.id&&cellEdit.field===item.column.name" class="dw-cell-editor" @click.stop @dblclick.stop>
          <DatasetCellControl :model-value="cellEdit" :field="item.column.name" :definition="snapshot.descriptor.fields?.[item.column.name]" :allow-type-selection="cellEdit.originalPresence!=='value'" @update:model-value="value=>{if(cellEdit)Object.assign(cellEdit,value)}" @commit="stageCellEditing" @cancel="cancelCell" @blur="blurCell"/>
          <div><small>{{cellEdit.kind}}</small><button type="button" class="dw-icon" :aria-label="'暂存 '+item.column.name" title="加入草稿（Enter）" @mousedown.prevent @click="stageCellEditing"><Check :size="14"/></button><button type="button" class="dw-icon" :aria-label="'取消编辑 '+item.column.name" title="取消（Esc）" @mousedown.prevent @click="cancelCell"><X :size="14"/></button></div><p v-if="cellError" role="alert">{{cellError}}</p>
        </div>
        <span v-else class="dw-cell-text" :title="cellStateTitle(row.id,item.column.name)??shownCell(row.data,item.column.name)"><template v-if="optionCellValues(row.data,item.column.name)"><span v-for="(value,position) in optionCellValues(row.data,item.column.name)" :key="position" class="dw-option-value" :class="{'dw-option-multi':Array.isArray(row.data[item.column.name])}" :style="{color:value.color}">{{value.text}}</span></template><template v-else>{{shownCell(row.data,item.column.name)}}</template></span>
      </td><td v-else-if="item.kind==='evaluation'" class="dw-historical-family"><code>{{historicalFamily(row.id)}}</code><small>历史证据 · 只读</small></td><td v-else-if="item.column.id==='system.updated_at'" class="dw-system-time" :title="activityHelp(row.id)"><span>{{row.isNew&&!snapshot.rowActivity?.[row.id]?'待首次提交':activityTime(row.id)}}</span><small v-if="snapshot.rowActivity?.[row.id]?.source==='source-file'">源文件时间</small></td><td v-else class="dw-system-actor" :title="activityHelp(row.id)">{{row.isNew&&!snapshot.rowActivity?.[row.id]?'待首次提交':activityActor(row.id)}}</td></template>
    </tr></tbody>
  </table><div v-if="!viewRows.length" class="dw-empty"><Search :size="28"/><strong>{{snapshot.totalRows?'没有匹配样本':'数据集目前没有样本'}}</strong><p v-if="!snapshot.totalRows">可以添加首条样本，或导入CSV、JSONL、受管ZIP；字段可先在项目设置配置。</p><div v-if="!snapshot.totalRows&&canAddRows" class="dw-empty-actions"><button class="btn btn-primary" @click="append">添加首条样本</button><button class="btn" @click="openImport">导入样本</button><button class="btn btn-ghost" @click="router.push({path:base+'/settings',query:{branch}})">配置样本字段</button></div><button v-if="snapshot.totalRows" class="btn" @click="clearFilters">清除筛选</button></div></div>
  <footer class="dw-pagination"><span>第 {{page}} / {{pages}} 页</span><div><button class="btn" :disabled="page<=1||loading" @click="stageEditing()&&(page--,load())"><ArrowLeft :size="14"/>上一页</button><button class="btn" :disabled="page>=pages||loading" @click="stageEditing()&&(page++,load())">下一页<ArrowRight :size="14"/></button></div></footer></div></div>
  <div v-if="inspectorOpen&&current" class="dw-inspector-backdrop" @click.self="closeInspector"><aside class="dw-inspector" role="dialog" aria-modal="false" aria-label="样本详情">
    <header class="dw-property-heading"><div><strong>样本属性</strong><code :title="selected">{{display(current.id??current.uid??selected)}}</code></div><div class="dw-property-pager"><span>本页 {{viewRows.findIndex(row=>row.id===selected)+1}} / {{viewRows.length}}</span><button class="dw-icon" aria-label="上一条样本" :disabled="viewRows.findIndex(row=>row.id===selected)<=0" @click="moveSample(-1)"><ArrowLeft :size="16"/></button><button class="dw-icon" aria-label="下一条样本" :disabled="viewRows.findIndex(row=>row.id===selected)>=viewRows.length-1" @click="moveSample(1)"><ArrowRight :size="16"/></button><button class="dw-icon" aria-label="关闭样本详情" @click="closeInspector"><X :size="19"/></button></div></header>
    <div class="dw-property-actions"><button class="btn btn-ghost" :disabled="!canEdit||saving||editing" @click="edit">编辑内容</button><button class="btn btn-ghost" title="复制样本 JSON" @click="copyJson"><Copy :size="13"/>复制 JSON</button><button class="btn btn-ghost" :disabled="!canAddRows||saving" @click="duplicate"><Copy :size="13"/>复制为新样本</button><span v-if="rowEditState(selected)" class="dw-property-status" :class="{'dw-pending-key':rowEditState(selected)==='modified','dw-committed-key':rowEditState(selected)==='committed'}" :title="rowStateText(selected)">{{rowStateBadge(selected)}}</span><button class="dw-icon dw-property-delete" :disabled="!canEdit||saving" aria-label="删除样本" title="删除样本" @click="remove"><Trash2 :size="14"/></button></div>
    <p class="dw-sample-schema"><Tags :size="13"/><span>{{sampleSchemaTitle}}</span><code :title="branch">{{branch}}</code></p>
    <nav class="dw-property-tabs" role="tablist" aria-label="样本详情分组" @keydown="inspectorTabKeydown"><button id="dw-property-content-tab" type="button" role="tab" aria-controls="dw-property-content-panel" :aria-selected="inspectorTab==='content'" :tabindex="inspectorTab==='content'?0:-1" @click="inspectorTab='content'">内容属性</button><button id="dw-property-labels-tab" type="button" role="tab" aria-controls="dw-property-labels-panel" :aria-selected="inspectorTab==='labels'" :tabindex="inspectorTab==='labels'?0:-1" @click="inspectorTab='labels'">人工标注 <small>{{scopeColumns('row').length}}</small></button><button id="dw-property-info-tab" type="button" role="tab" aria-controls="dw-property-info-panel" :aria-selected="inspectorTab==='info'" :tabindex="inspectorTab==='info'?0:-1" @click="inspectorTab='info'">信息与证据</button></nav>
    <p v-if="localError" class="dw-error dw-property-error" role="alert">{{localError}}</p>
    <div class="dw-property-body">
    <section v-show="inspectorTab==='content'" id="dw-property-content-panel" class="dw-property-content" role="tabpanel" aria-labelledby="dw-property-content-tab"><div v-if="editing" class="dw-record-editor"><p>编辑加入本轮草稿，保存私有草稿后仍需统一提交。身份、来源及源真值字段只读。</p><textarea v-model="json" :disabled="loading||saving" rows="16" spellcheck="false" aria-label="编辑样本 JSON"/><div><button class="btn" @click="editing=false">取消编辑</button><button class="btn btn-primary" @click="stageEditing">加入草稿</button></div></div><DatasetSampleFields v-else :sample-key="selected" :record="stagedCurrent??current" :fields="snapshot.descriptor.fields"/></section>
    <section v-show="inspectorTab==='labels'" id="dw-property-labels-panel" class="dw-property-scroll" role="tabpanel" aria-labelledby="dw-property-labels-tab">
  <section class="dw-inspector-section"><header><h3>我的样本标注</h3><button class="dw-text-button" :disabled="!snapshot.capabilities?.feedback||!rowMay(selected,'feedback')" @click="drawer='feedback'">反馈缺项</button></header><p class="dw-muted">当前分支样本的人工判断，与原始字段及源真值分开。未填写、不确定与不适用含义不同；其他人的意见仅作参考。</p><p v-if="!canAssign" class="dw-notice">当前身份或任务范围不允许修改此样本。</p><DatasetLabelFields :columns="scopeColumns('row')" :required-ids="requiredLabelIds('row')" scope="row" :model-value="labelValues('row',selected)" :disabled="!canAssign||saving" @update:model-value="queueLabels('row',$event,selected)"/></section>
  <section class="dw-inspector-section"><header><h3>片段与步骤</h3><button class="dw-text-button" :disabled="!canAssign" @click="openFine"><Plus :size="13"/>添加</button></header><div v-for="annotation in [...fineAnnotations.spans,...fineAnnotations.steps]" :key="annotation.id" class="dw-fine-item"><div><code>{{annotation.pointer}}</code><small>{{'start'in annotation?`码点 [${annotation.start}, ${annotation.end})`:'结构化步骤'}}</small></div><button class="dw-icon" :disabled="!canAssign" aria-label="移除精细标注" @click="removeFine(annotation.id)"><X :size="13"/></button></div><p v-if="!fineAnnotations.spans.length&&!fineAnnotations.steps.length" class="dw-muted">尚无当前操作者的精细标注。</p></section>
  <section v-if="!currentRecord&&Object.keys(referenceValues).length&&!otherOpinions.length" class="dw-inspector-section dw-reference"><h3>当前版本既有标签</h3><p class="dw-muted">只读参考，尚未复制为我的意见。</p><pre>{{JSON.stringify(referenceValues,null,2)}}</pre><button class="btn" :disabled="!canAssign||saving" @click="copyReference(referenceValues)">复制标签到我的草稿</button></section>
  <section v-if="otherOpinions.length" class="dw-inspector-section dw-reference"><header><h3>其他标注者的意见</h3><span class="dw-muted">只读参考</span></header><details v-for="record in otherOpinions" :key="record.actor.id"><summary>{{record.actor.name}} · {{record.updatedAt.slice(0,10)}}</summary><dl><template v-for="(value,key) in record.values" :key="key"><dt>{{scopeColumns('row').find(column=>column.id===key)?.name??key}}</dt><dd>{{displayLabel(String(key),value)}}</dd></template></dl><button class="btn" :disabled="!canAssign||saving" @click="copyOpinion(record)">复制标签到我的草稿</button></details></section>
    </section>
    <section v-show="inspectorTab==='info'" id="dw-property-info-panel" class="dw-property-scroll" role="tabpanel" aria-labelledby="dw-property-info-tab">
      <section class="dw-inspector-section"><header><h3>版本与操作记录</h3><span class="dw-muted">{{historical?'固定历史版本':'当前分支'}}</span></header><dl class="dw-property-info"><dt>条目身份</dt><dd><code>{{selected}}</code></dd><dt>最后修改</dt><dd>{{activityTime(selected)}}</dd><dt>最后操作人</dt><dd>{{activityActor(selected)}}</dd><dt>版本</dt><dd><code>{{snapshot.commitId}}</code></dd><dt>内容摘要</dt><dd><code>{{snapshot.contentHashes[selected]??'尚未提交'}}</code></dd></dl><p class="dw-muted dw-property-evidence-help">{{activityHelp(selected)}}</p></section>
      <section v-if="snapshot.evaluation?.enabled" class="dw-inspector-section"><header><h3>历史同源证据</h3><span class="dw-muted">只读</span></header><p>样本家族：<code>{{historicalFamily(selected)}}</code>。此记录不决定本次发布范围。</p></section>
      <section v-if="rowAttachments.length" class="dw-inspector-section"><header><h3>附件与文件标签</h3><span class="dw-muted">{{rowAttachments.length}} 个关联文件</span></header><button v-for="item in rowAttachments" :key="item.path" class="dw-attachment" @click="openAttachment(item.path)"><FileArchive :size="17"/><span>{{item.name}}<small>{{item.bytes?Math.ceil(item.bytes/1024)+' KiB':'关联文件'}} · 查看内容与文件标签</small></span><ChevronDown :size="14"/></button></section>
      <section class="dw-inspector-section"><header><h3>独立标注与版本证据</h3></header><div v-for="record in snapshot.labelRecords.filter(item=>item.scope==='row'&&item.rowId===selected)" :key="record.actor.id" class="dw-evidence"><strong>{{record.actor.name}}</strong><small>{{record.updatedAt}}</small><code>{{record.fingerprint.slice(0,16)}}</code><span v-if="record.contentHash!==snapshot.contentHashes[selected]" class="dw-warning">内容已改变，需重新检查标注</span></div><p v-if="!snapshot.labelRecords.some(item=>item.scope==='row'&&item.rowId===selected)" class="dw-muted">暂无已保存的独立标注证据。</p></section>
    </section></div></aside></div>
  <footer v-if="dirty||hasUncommitted" class="dw-savebar"><div><Save :size="17"/><strong>{{pending.length+(editing&&json!==jsonBaseline?1:0)}} 项{{dirty?'未保存编辑':'私有草稿更改'}}</strong><span>保存草稿不产生提交</span></div><button class="btn" :disabled="saving||!dirty||!!serverDraftIssue" @click="saveLocalDraft()"><Save :size="14"/>保存私有草稿</button><button class="btn" :disabled="saving||!!serverDraftIssue||!pending.length" @click="inspectDiff">查看变更</button><input v-model="message" aria-label="提交说明" placeholder="填写本次提交说明"/><button class="btn btn-primary" :disabled="saving||!message.trim()||!!serverDraftIssue" @click="save"><LoaderCircle v-if="saving" class="spin" :size="15"/>{{saving?'处理中…':'提交到分支'}}</button></footer>
  </template>
</section>
<div v-if="drawer&&snapshot" class="modal-backdrop dw-modal-backdrop" @click.self="closeDrawer"><section class="modal dw-modal" :class="{'dw-attachment-modal':drawer==='file'}" role="dialog" aria-modal="true" :aria-label="drawer==='file'?'附件与文件标签':drawer==='source-bulk'?'批量编辑样本字段与标签':drawer==='labels'?'样本人工标签':drawer==='bulk'?'批量标注':drawer==='fine'?'精细标注':drawer==='append'?'添加样本':'反馈缺项'"><header><div><h2>{{drawer==='file'?'附件与文件标签':drawer==='source-bulk'?'批量编辑样本字段与标签':drawer==='labels'?'样本人工标签':drawer==='bulk'?'批量标注':drawer==='fine'?'片段与步骤标注':drawer==='append'?'添加样本':'反馈缺项'}}</h2><p>{{drawer==='file'?'仅作用于此文件，保存后与样本标注共同版本化。':drawer==='bulk'?`将给已选择的 ${selectedRows.length} 条样本赋值，单次最多 500 条。`:drawer==='fine'?'锚点绑定字段、内容摘要和 Unicode 码点位置。':''}}</p></div><button class="dw-icon" aria-label="关闭面板" @click="closeDrawer"><X :size="20"/></button></header><p v-if="localError" class="dw-error">{{localError}}</p>
  <template v-if="drawer==='labels'"><section class="dw-single-label-scope"><strong>{{display(current?.id??current?.uid??selected)}}</strong><p>只编辑我的样本标签，源内容与其他标注者的意见保持独立。修改自动加入本轮草稿，返回表格后可保存私有草稿，再统一提交到分支。</p><p v-if="!rowCanAssign(selected)" class="dw-notice">当前身份、任务范围或版本已不允许修改此样本。</p></section><DatasetLabelFields :columns="scopeColumns('row')" :required-ids="requiredLabelIds('row')" scope="row" :model-value="labelValues('row',selected)" :disabled="!rowCanAssign(selected)" @update:model-value="queueLabels('row',$event,selected)"/><footer><button class="btn btn-primary" type="button" @click="closeDrawer">完成，返回表格</button></footer></template>
  <template v-if="drawer==='file'"><div class="dw-file-title"><FileArchive :size="18"/><strong>{{attachment.split('/').pop()}}</strong><button v-if="/\.zip$/i.test(attachment)" class="btn" @click="emit('compare-archive',attachment)">比较版本</button><a :href="rawUrl" class="btn" download><Download :size="14"/>下载附件</a></div><ArchivePreview v-if="/\.zip$/i.test(attachment)" :base="base" :branch="pinned" :path="attachment" compact/><p v-else class="dw-muted">此附件可直接下载；文件内容作为数据处理。</p><div class="dw-file-labels"><h3>文件标签</h3><DatasetLabelFields :columns="scopeColumns('file')" :required-ids="requiredLabelIds('file')" scope="file" :model-value="labelValues('file',undefined,attachment)" :disabled="historical||!snapshot.capabilities?.editFileLabels" @update:model-value="queueLabels('file',$event,undefined,attachment)"/></div></template>
  <template v-if="drawer==='source-bulk'"><p v-if="sourceBulkLoading" class="dw-muted" role="status">正在读取 {{sourceBulkIds.length}} 条已选样本，包含其他页的选择…</p><p v-if="sourceBulkError" class="dw-error" role="alert">{{sourceBulkError}}<button class="btn" @click="hydrateSourceBulk">重新读取所选样本</button></p><DatasetBulkEditor v-model="sourceBulkRequest" :selected-ids="sourceBulkIds" :pending-operations="pending" :rows="sourceBulkRows" :fields="snapshot.descriptor.fields??{}" :source-columns="allColumns" :label-columns="scopeColumns('row')" :identity-field="snapshot.descriptor.identityField" :disabled="sourceBulkLoading||!!sourceBulkError||saving||historical" @apply="applySourceBulk" @cancel="closeDrawer"/></template>
  <template v-if="drawer==='bulk'"><section class="dw-bulk-scope"><strong>本次可处理 {{bulkCandidateIds.length}} / 已选 {{selectedRows.length}} 条</strong><p>仅向以下稳定身份写入我的标签草稿，未选中的匹配样本不会修改；超出权限、已删除或已撤销新增的条目不处理。</p><details><summary>核对条目身份</summary><pre>{{bulkCandidateIds.join('\n')}}</pre></details></section><DatasetLabelFields :columns="scopeColumns('row')" :required-ids="requiredLabelIds('row')" scope="row" v-model="bulkValues" :disabled="!bulkCandidateIds.length||saving"/><footer><button class="btn btn-primary" :disabled="!Object.keys(bulkValues).length||!bulkCandidateIds.length" @click="bulkApply">加入 {{bulkCandidateIds.length}} 条草稿更改</button></footer></template>
  <template v-if="drawer==='feedback'"><label class="dw-form-field">缺少的维度、选项或释义<textarea v-model="feedback" rows="6" maxlength="8000" placeholder="说明当前规范缺少什么，不需要在此粘贴敏感记录。"/></label><footer><button class="btn btn-primary" :disabled="!feedback.trim()" @click="submitFeedback">提交给规范维护者</button></footer></template>
  <template v-if="drawer==='append'"><p v-if="appendInfo" class="dw-copy-note">{{appendInfo}}</p><label class="dw-form-field">新样本 JSON<textarea v-model="json" rows="15" spellcheck="false"/></label><footer><button class="btn btn-primary" :disabled="!canAddRows" @click="addRecord">加入草稿样本</button></footer></template>
  <template v-if="drawer==='fine'"><div class="dw-inline-fields"><label class="dw-form-field">粒度<select v-model="fineKind"><option value="span">字符片段</option><option value="step">结构化步骤</option></select></label><label class="dw-form-field">实际字段 / 步骤<select v-model="finePointer"><option value="">请选择</option><option v-for="target in fineTargets" :key="target.pointer" :value="target.pointer">{{target.pointer||'整条样本'}}</option></select></label></div><template v-if="fineKind==='span'"><textarea class="dw-source-selection" :value="fineText" readonly rows="5" aria-label="选择源文本片段" @select="captureSelection"/><div class="dw-inline-fields"><label class="dw-form-field">起始码点<input v-model.number="fineStart" type="number" min="0"/></label><label class="dw-form-field">结束码点（不含）<input v-model.number="fineEnd" type="number" min="1"/></label></div></template><DatasetLabelFields :columns="scopeColumns('row')" :required-ids="requiredLabelIds('row')" scope="row" v-model="fineValues"/><label class="dw-form-field">证据备注<textarea v-model="fineNote" rows="2" maxlength="8000"/></label><footer><button class="btn btn-primary" @click="addFine">加入精细标注</button></footer></template>
</section></div>
<div v-if="navigationDialog" class="modal-backdrop dw-navigation-backdrop"><section class="modal dw-navigation-dialog" role="dialog" aria-modal="true" aria-label="原始输入尚未安全保存"><h2>输入保留失败</h2><p>当前原始输入仍在本页，未丢弃，也无需先提交到分支。保存成功后即可切换页面。</p><p v-if="navigationError" class="dw-error" role="alert">{{navigationError}}</p><div><button v-if="checkpointConflict" class="btn btn-primary" :disabled="navigationBusy||checkpointRecovering" @click="chooseNavigation('recover')">保留两份输入后切换</button><button v-else class="btn btn-primary" :disabled="navigationBusy" @click="chooseNavigation('preserve')">重试保留后切换</button><button class="btn" @click="downloadCheckpoint(captureCheckpoint())">下载当前输入</button><button class="btn btn-ghost" :disabled="navigationBusy" @click="chooseNavigation('cancel')">留在本页</button></div><small>未完成输入可保留到本机私有 BFF。冲突恢复会重新核对最新副本，将另一页面的真实输入只读保留；当前输入继续编辑，不应用到分支。</small></section></div>
<div v-if="showDiff&&draftDiff" class="modal-backdrop dw-modal-backdrop" @click.self="showDiff=false"><section class="modal dw-diff-modal" role="dialog" aria-modal="true" aria-label="本机草稿变更"><header><div><h2>本机草稿变更</h2><p>{{branch}} · 基点 {{draftDiff.draft.baseCommit.slice(0,10)}} · r{{draftDiff.draft.draftRevision}}；尚未提交到分支。</p></div><button class="dw-icon" aria-label="关闭变更列表" @click="showDiff=false"><X :size="20"/></button></header><details v-for="(change,index) in draftDiff.changes" :key="index" :open="draftDiff.changes.length===1"><summary><span>{{change.op==='evaluation'?'历史评测元数据':change.op==='assign'?'标签':change.op==='update'?'修改样本':change.op==='append'?'新增样本':change.op==='delete'?'删除样本':change.op==='readme'?'修改概览':'反馈'}}</span><code>{{change.rowId??change.path??(change.scope==='dataset'?'数据集':'')}}</code><small>{{change.fields.join(' · ')}}</small><span class="dw-diff-toggle"><ChevronDown :size="13"/>展开前后值</span></summary><div class="dw-diff-columns"><div><h4>基点版本</h4><pre>{{change.before===undefined?'（无）':JSON.stringify(change.before,null,2)}}</pre></div><div><h4>草稿版本</h4><pre>{{change.after===undefined?'（无）':JSON.stringify(change.after,null,2)}}</pre></div></div></details><footer><button class="btn" @click="showDiff=false">返回编辑</button></footer></section></div>
<DatasetImportPanel v-if="importOpen" :base="base" :branch="branch" :expected-commit="snapshot?.commitId??emptySetup?.commitId??''" @close="importOpen=false" @imported="imported"/>
</template>
<style scoped src="./DatasetWorkbench.css"></style>
